package br.gov.dere.persistence;
import jakarta.persistence.*; import java.time.Instant; import java.util.*;
@Entity @Table(name="dere_user") public class DereUserEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,unique=true) private String login; @Column(name="password_hash",nullable=false) private String passwordHash; @Column(name="display_name",nullable=false) private String displayName; private boolean active=true; @Column(name="created_at") private Instant createdAt=Instant.now(); @ManyToMany @JoinTable(name="dere_user_entity",joinColumns=@JoinColumn(name="user_id"),inverseJoinColumns=@JoinColumn(name="entity_id")) private Set<DereEntityEntity> entities=new HashSet<>(); protected DereUserEntity(){} public DereUserEntity(String l,String h,String n){login=l;passwordHash=h;displayName=n;} public Long getId(){return id;} public String getLogin(){return login;} public String getPasswordHash(){return passwordHash;} public String getDisplayName(){return displayName;} public Set<DereEntityEntity> getEntities(){return entities;}}
